#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;

class Item {
public:
    Item(int id, const string& name) : id(id), name(name) {}
    virtual ~Item() = default;
    virtual string kind() const { return "东西"; }
    virtual int keepDays() const { return 7; }
    int id;
    string name;
    bool out = false;
};

class Book : public Item {
public:
    Book(int id, const string& name) : Item(id, name) {}
    string kind() const override { return "书"; }
    int keepDays() const override { return 14; }
};

class Magazine : public Item {
public:
    Magazine(int id, const string& name) : Item(id, name) {}
    string kind() const override { return "杂志"; }
    int keepDays() const override { return 3; }
};

int main() {
    vector<unique_ptr<Item>> shelf;
    shelf.push_back(make_unique<Book>(1, "鱼干小百科"));
    shelf.push_back(make_unique<Magazine>(2, "猫粮月报"));
    shelf.push_back(make_unique<Book>(3, "大肥鱼自传"));
    shelf[1]->out = true;

    for (const auto& it : shelf) {
        cout << it->id << " " << it->name << "（" << it->kind() << "，可借 " << it->keepDays() << " 天）"
             << (it->out ? " 借出" : " 在架") << endl;
    }
    return 0;
}

#include <algorithm>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;

class Item {
public:
    Item(int id, const string& name) : id(id), name(name) {}
    int id;
    string name;
    bool out = false;
};

class Library {
public:
    static Library& getInstance() {
        static Library only;
        return only;
    }
    void add(int id, const string& name) { shelf.push_back(make_unique<Item>(id, name)); }

    bool borrow(int id) {
        Item* it = find(id);
        if (!it || it->out) return false;
        it->out = true;
        return true;
    }

    bool giveBack(int id) {
        Item* it = find(id);
        if (!it || !it->out) return false;
        it->out = false;
        return true;
    }

    int outCount() const {
        return count_if(shelf.begin(), shelf.end(), [](const unique_ptr<Item>& p) { return p->out; });
    }

private:
    Item* find(int id) {
        for (auto& it : shelf) if (it->id == id) return it.get();
        return nullptr;
    }
    Library() = default;
    vector<unique_ptr<Item>> shelf;
};

int main() {
    Library& lib = Library::getInstance();
    lib.add(1, "鱼干小百科");
    lib.add(2, "猫粮月报");

    cout << (lib.borrow(2) ? "办好了" : "办不了") << " 2" << endl;
    cout << (lib.borrow(2) ? "办好了" : "办不了") << " 2" << endl;
    cout << (lib.giveBack(2) ? "办好了" : "办不了") << " 2" << endl;
    cout << (lib.giveBack(1) ? "办好了" : "办不了") << " 1" << endl;
    cout << "借出去 " << lib.outCount() << " 件" << endl;
    return 0;
}
